func identityRekeyMaterialTarget(verified VerifiedIdentityRekey, inputs TrustInputs, now time.Time) (GenerationTarget, []byte, identityMaterialPredecessors, error) {
	current, err := verified.VerifyCurrent(inputs, now)
	if err != nil {
		return GenerationTarget{}, nil, identityMaterialPredecessors{}, err
	}
	if err := identityrekey.ValidatePreviousMaterialPins(current.journal.PreviousMaterialSHA256); err != nil {
		return GenerationTarget{}, nil, identityMaterialPredecessors{}, err
	}
	target, err := GenerationTargetFromAccepted(current.Accepted())
	return target, current.Values()[2], identityMaterialPredecessors{installed: current.journal.PreviousMaterialSHA256["installed"],
		durable: current.journal.PreviousMaterialSHA256["durable"]}, err
}

func (store MaterialStore) VerifyIdentityRekeyMaterialPredecessors(verified VerifiedIdentityRekey, inputs TrustInputs, now time.Time) error {
	_, chain, previous, err := identityRekeyMaterialTarget(verified, inputs, now)
	if err != nil {
		return err
	}
	dir, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	return store.verifyIdentityMaterialPredecessors(dir, chain, previous)
}

// AdoptIdentityRekeyGeneration replaces only the two opaque local predecessors
// pinned by this current root checkpoint. Ordinary adoption stays strict.
func (store MaterialStore) AdoptIdentityRekeyGeneration(verified VerifiedIdentityRekey, inputs TrustInputs,
	files map[string][]byte, config []byte, now time.Time,
) error {
	target, chain, previous, err := identityRekeyMaterialTarget(verified, inputs, now)
	if err != nil {
		return err
	}
	return store.adoptGeneration(target, verified.InstallationRoots(inputs), chain, files, config, verified.InstallationTime(now), &previous)
}

func (store MaterialStore) FinishIdentityRekeyMaterialAdoption(verified VerifiedIdentityRekey, inputs TrustInputs, configPath string, now time.Time) error {
	target, chain, previous, err := identityRekeyMaterialTarget(verified, inputs, now)
	if err != nil {
		return err
	}
	if err := store.VerifyIdentityRekeyMaterialAdoption(target, verified.InstallationRoots(inputs), chain, verified.InstallationTime(now)); err != nil {
		return err
	}
	dir, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	if err := store.verifyIdentityMaterialPredecessors(dir, chain, previous); err != nil {
		return err
	}
	return store.finish(dir, target, verified.InstallationRoots(inputs), configPath, verified.InstallationTime(now), &previous, nil)
}

func verifyInstalledGenerationChain(installed, chainWire []byte, chain []trust.Envelope, previous *identityMaterialPredecessors) error {
	if previous != nil {
		if bytes.Equal(installed, chainWire) || digest(installed) == previous.installed {
			return nil
		}
		return ErrMaterial
	}
	held, err := bootstrap.DecodeMaterialGenerationChain(installed)
	if err != nil || !chainIs(held, chainWire) && !bootstrap.ExtendsMaterialGenerationChain(chain, held) {
		return ErrMaterial
	}
	return nil
}

func (store MaterialStore) verifyIdentityMaterialPredecessors(dir int, chainWire []byte, previous identityMaterialPredecessors) error {
	if !markerDigestRE.MatchString(previous.installed) || !markerDigestRE.MatchString(previous.durable) || len(chainWire) == 0 || store.chainCopy == "" {
		return ErrMaterial
	}
	installed, err := readUnpinned(dir, MaterialGenerationsFile, store.serviceUID, store.serviceGID, maxGenerationChainBytes)
	if err != nil || !bytes.Equal(installed, chainWire) && digest(installed) != previous.installed {
		return errors.Join(ErrMaterial, err)
	}
	copyDir, err := openMaterialDirectory(filepath.Dir(store.chainCopy), uint32(os.Geteuid()), uint32(os.Getegid()), 0o755, store.allowUnsafeAncestors)
	if err != nil {
		return err
	}
	defer unix.Close(copyDir)
	fd, err := unix.Openat(copyDir, filepath.Base(store.chainCopy), unix.O_RDONLY|unix.O_NONBLOCK|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
	if err != nil {
		return err
	}
	file := os.NewFile(uintptr(fd), store.chainCopy)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Mode&0o7777 != 0o644 ||
		stat.Uid != uint32(os.Geteuid()) || stat.Gid != uint32(os.Getegid()) || stat.Nlink != 1 || stat.Size <= 0 || stat.Size > maxGenerationChainBytes {
		return ErrMaterial
	}
	wire, err := io.ReadAll(io.LimitReader(file, maxGenerationChainBytes+1))
	if err != nil || int64(len(wire)) != stat.Size || !bytes.Equal(wire, chainWire) && digest(wire) != previous.durable {
		return errors.Join(ErrMaterial, err)
	}
	return nil
}

material_finish_verify.text:
func (store MaterialStore) VerifyIdentityRekeyMaterialAdoption(target GenerationTarget, roots trust.Keyring, chainWire []byte, now time.Time) error {
	chain, err := bootstrap.DecodeMaterialGenerationChain(chainWire)
	if err != nil {
		return err
	}
	verified, err := target.VerifyChain(chain, roots, now)
	if err != nil {
		return err
	}
	newest := verified[len(verified)-1]
	if newest.Fingerprint() != target.MaterialGenerationSHA256 {
		return ErrMaterial
	}
	dir, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	staging, err := store.openStaging(dir)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	defer unix.Close(staging)
	names, err := stagedNames(staging)
	if err != nil {
		return err
	}
	committed := slices.Contains(names, MaterialGenerationsFile)
	if committed {
		staged, err := store.readStaged(staging, MaterialGenerationsFile, "", maxGenerationChainBytes)
		if err != nil || !bytes.Equal(staged, chainWire) {
			return ErrMaterial
		}
	}
	refs := map[string]bootstrap.SecretReference{}
	for _, reference := range newest.Generation().Secrets {
		if reference.Slot == "" || reference.Slot == target.Slot {
			refs[reference.TargetFile] = reference
		}
	}
	for _, name := range names {
		if name == MaterialGenerationsFile || committed && name == verifiedMaterialTemporary {
			continue
		}
		reference, exists := refs[name]
		if !committed && name == generationChainTemporary {
			reference.MaxBytes, exists = maxGenerationChainBytes, true
		}
		if !exists {
			return ErrMaterial
		}
		if !committed {
			// No commit record exists: Finish discards only owned target names.
			var stat unix.Stat_t
			if err := unix.Fstatat(staging, name, &stat, unix.AT_SYMLINK_NOFOLLOW); err != nil ||
				stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Mode&0o7777 != 0o600 || stat.Nlink != 1 ||
				(stat.Uid != store.serviceUID || stat.Gid != store.serviceGID) &&
					(stat.Uid != uint32(os.Geteuid()) || stat.Gid != uint32(os.Getegid())) || stat.Size < 0 || stat.Size > reference.MaxBytes {
				return ErrMaterial
			}
			continue
		}
		wire, err := store.readStaged(staging, name, reference.SHA256, reference.MaxBytes)
		clear(wire)
		if err != nil {
			return err
		}
	}
	return nil
}

adopt.text:
func (store MaterialStore) AdoptGeneration(target GenerationTarget, roots trust.Keyring, chainWire []byte, files map[string][]byte, config []byte, now time.Time) error {
	return store.adoptGeneration(target, roots, chainWire, files, config, now, nil)
}

func (store MaterialStore) adoptGeneration(target GenerationTarget, roots trust.Keyring, chainWire []byte, files map[string][]byte, config []byte,
	now time.Time, previous *identityMaterialPredecessors,
) error {
	chain, err := bootstrap.DecodeMaterialGenerationChain(chainWire)
	if err != nil {
		return err
	}
	verified, err := target.VerifyChain(chain, roots, now)
	if err != nil {
		return err
	}
	if err := stagedFilesMatch(chain, target.Slot, files); err != nil {
		return err
	}
	checked := maps.Clone(files)
	if config != nil {
		checked[GenerationConfigFile(target.Slot)] = config
	}
	if err := target.VerifyFiles(verified[len(verified)-1].Generation(), materialReader(checked), now); err != nil {
		return err
	}
	dir, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return fmt.Errorf("open service-owned credential directory: %w", err)
	}
	defer unix.Close(dir)
	if previous != nil {
		if err := store.verifyIdentityMaterialPredecessors(dir, chainWire, *previous); err != nil {
			return err
		}
	}
	installed, err := readUnpinned(dir, MaterialGenerationsFile, store.serviceUID, store.serviceGID, maxGenerationChainBytes)
	if err == nil {
		if err := verifyInstalledGenerationChain(installed, chainWire, chain, previous); err != nil {
			return err
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	if err := unix.Mkdirat(dir, generationStaging, 0o700); err != nil {
		return fmt.Errorf("create generation staging: %w", err)
	}
	if err := unix.Fchownat(dir, generationStaging, int(store.serviceUID), int(store.serviceGID),
		unix.AT_SYMLINK_NOFOLLOW); err != nil {
		return fmt.Errorf("own generation staging: %w", err)
	}
	staging, err := store.openStaging(dir)
	if err != nil {
		return err
	}
	defer unix.Close(staging)
	for _, name := range slices.Sorted(maps.Keys(files)) {
		if err := store.writeStaged(staging, name, files[name]); err != nil {
			return fmt.Errorf("stage %s: %w", name, err)
		}
	}
	if err := store.writeStaged(staging, generationChainTemporary, chainWire); err != nil {
		return fmt.Errorf("commit staged generation: %w", err)
	}
	if err := unix.Renameat2(staging, generationChainTemporary, staging, MaterialGenerationsFile, unix.RENAME_NOREPLACE); err != nil {
		return err
	}
	if err := unix.Fsync(staging); err != nil {
		return err
	}
	snapshot := maps.Clone(files)
	snapshot[MaterialGenerationsFile] = chainWire
	return store.rollForward(dir, staging, append(slices.Sorted(maps.Keys(files)), MaterialGenerationsFile), snapshot, previous)
}

finish.text:
func (store MaterialStore) finish(dir int, target GenerationTarget, roots trust.Keyring, configPath string, now time.Time,
	previous *identityMaterialPredecessors, replacement []bootstrap.VerifiedMaterialGeneration,
) error {
	staging, err := store.openStaging(dir)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	defer unix.Close(staging)
	names, err := stagedNames(staging)
	if err != nil {
		return err
	}
	if slices.Contains(names, verifiedMaterialTemporary) {
		var stat unix.Stat_t
		if err := unix.Fstatat(staging, verifiedMaterialTemporary, &stat, unix.AT_SYMLINK_NOFOLLOW); err != nil ||
			stat.Uid != uint32(os.Geteuid()) || stat.Gid != uint32(os.Getegid()) || stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Mode&0o7777 != 0o600 || stat.Nlink != 1 {
			return ErrMaterial
		}
		if !slices.Contains(names, MaterialGenerationsFile) {
			return ErrMaterial
		}
		names = slices.DeleteFunc(names, func(name string) bool { return name == verifiedMaterialTemporary })
	}
	if slices.Contains(names, MaterialGenerationsFile) {
		chainWire, err := store.readStaged(staging, MaterialGenerationsFile, "", maxGenerationChainBytes)
		if err != nil {
			return err
		}
		chain, err := bootstrap.DecodeMaterialGenerationChain(chainWire)
		if err != nil {
			return err
		}
		var verified []bootstrap.VerifiedMaterialGeneration
		if replacement == nil {
			verified, err = target.VerifyChain(chain, roots, now)
		} else {
			verified, err = target.VerifyAdoptedChain(chain, roots)
			if err == nil && (len(replacement) <= len(verified) || replacement[len(verified)-1].Fingerprint() != verified[len(verified)-1].Fingerprint()) {
				err = ErrMaterial
			}
		}
		if err != nil {
			return fmt.Errorf("verify committed generation stage: %w", err)
		}
		generation := verified[len(verified)-1].Generation()
		installed, err := readUnpinned(dir, MaterialGenerationsFile, store.serviceUID, store.serviceGID, maxGenerationChainBytes)
		if err == nil {
			if err := verifyInstalledGenerationChain(installed, chainWire, chain, previous); err != nil {
				return err
			}
		} else if !errors.Is(err, os.ErrNotExist) {
			return err
		}
		if err := store.stagedDigestsMatch(staging, generation, target.Slot, names); err != nil {
			return err
		}
		config, _, err := generationConfig(target, generation, configPath)
		if err != nil {
			return err
		}
		files, err := store.generationFiles(dir, staging, target, generation, config)
		if err != nil {
			return err
		}
		defer clearContents(files)
		// A fully verified current successor authorizes preserving this exact
		// predecessor floor; expired predecessor material never passes startup.
		if replacement == nil {
			if err := target.VerifyFiles(generation, materialReader(files), now); err != nil {
				return err
			}
		}
		files[MaterialGenerationsFile] = chainWire
		return store.rollForward(dir, staging, names, files, previous)
	}
	// Only exact observed local material names may be removed before commitment.
	allowed := bootstrap.MaterialGenerationFiles()
	cert, key := bootstrap.InterRegionTLSFiles(target.Slot)
	for _, name := range names {
		_, known := allowed[name]
		known = known || name == generationChainTemporary
		known = known || name == "interregion.jwt" || name == "interregion-ca.pem" || name == cert || name == key || name == target.Slot+".creds" ||
			name == bootstrap.LinkCredentialsFile
		if strings.HasPrefix(name, "leaf-") && strings.HasSuffix(name, ".creds") {
			peer := strings.TrimSuffix(strings.TrimPrefix(name, "leaf-"), ".creds")
			known = catalog.IsCell(strings.ToUpper(peer)) && peer == strings.ToLower(peer)
		}
		if !known {
			return fmt.Errorf("%w: uncommitted stage contains unrelated file %s", ErrMaterial, name)
		}
	}
	for _, name := range names {
		if err := unix.Unlinkat(staging, name, 0); err != nil {
			return err
		}
	}
	return removeStaging(dir)
}

roll_forward.text:
func (store MaterialStore) rollForward(dir, staging int, names []string, snapshot map[string][]byte, previous *identityMaterialPredecessors) error {
	if previous != nil {
		if err := store.verifyIdentityMaterialPredecessors(dir, snapshot[MaterialGenerationsFile], *previous); err != nil {
			return err
		}
	}
	// New inodes inside a root-only directory prevent the spool owner from
	// changing verified bytes between validation and their privileged rename.
	if err := unix.Fchown(staging, os.Geteuid(), os.Getegid()); err != nil {
		return err
	}
	if err := unix.Fsync(staging); err != nil {
		return err
	}
	for _, name := range names {
		if name == MaterialGenerationsFile {
			continue
		}
		if err := store.replaceStaged(staging, name, snapshot[name]); err != nil {
			return err
		}
		if err := unix.Renameat(staging, name, dir, name); err != nil {
			return fmt.Errorf("install %s: %w", name, err)
		}
	}
	if slices.Contains(names, MaterialGenerationsFile) {
		if err := unix.Fsync(dir); err != nil {
			return err
		}
		if err := store.replaceStaged(staging, MaterialGenerationsFile, snapshot[MaterialGenerationsFile]); err != nil {
			return err
		}
		if err := store.keepChain(staging); err != nil {
			return fmt.Errorf("keep %s: %w", MaterialGenerationsFile, err)
		}
		if err := unix.Renameat(staging, MaterialGenerationsFile, dir, MaterialGenerationsFile); err != nil {
			return err
		}
	}
	if err := unix.Fsync(dir); err != nil {
		return err
	}
	return removeStaging(dir)
}

write_staged.text:
func (store MaterialStore) writeStaged(staging int, name string, content []byte) error {
	if !markerNameRE.MatchString(name) && name != generationChainTemporary || len(content) == 0 ||
		int64(len(content)) > bootstrap.MaxSecretBytes && name != MaterialGenerationsFile && name != generationChainTemporary {
		return ErrMaterial
	}
	fd, err := unix.Openat(staging, name, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o600)
	if err != nil {
		return err
	}
	file := os.NewFile(uintptr(fd), name)
	if err := unix.Fchown(fd, int(store.serviceUID), int(store.serviceGID)); err != nil {
		_ = file.Close()
		return err
	}
	if err := unix.Fchmod(fd, 0o600); err != nil {
		_ = file.Close()
		return err
	}
	if n, err := file.Write(content); err != nil || n != len(content) {
		_ = file.Close()
		return errors.Join(err, io.ErrShortWrite)
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	return unix.Fsync(staging)
}

keep_chain.text:
func (store MaterialStore) keepChain(staging int) error {
	if store.chainCopy == "" {
		return nil
	}
	chain, err := readUnpinned(staging, MaterialGenerationsFile, store.serviceUID, store.serviceGID, maxGenerationChainBytes)
	if err != nil {
		return err
	}
	return writeSynced(store.chainCopy, chain)
}

func memoryFilesystem(fd int) bool {
	var fs unix.Statfs_t
	return unix.Fstatfs(fd, &fs) == nil && fs.Type == unix.TMPFS_MAGIC
}

material_read.text:
func readMaterial(dir int, name string, uid, gid uint32, want string, maximum int64) ([]byte, error) {
	if !markerNameRE.MatchString(name) || !markerDigestRE.MatchString(want) || maximum <= 0 || maximum > bootstrap.MaxSecretBytes {
		return nil, ErrMaterial
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != 0o600 || stat.Nlink != 1 ||
		stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrMaterial
	}
	content, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(content) == 0 || int64(len(content)) > maximum || digest(content) != want {
		clear(content)
		return nil, ErrMaterial
	}
	return content, nil
}

func openMaterialDirectory(path string, uid, gid uint32, mode uint32, allowUnsafeAncestors bool) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrMaterial
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	components := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for index, component := range components {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrMaterial
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			index < len(components)-1 && !allowUnsafeAncestors && (stat.Uid != 0 || stat.Mode&0o022 != 0) {
			unix.Close(fd)
			return -1, ErrMaterial
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != uid || stat.Gid != gid || stat.Mode&0o777 != mode {
		unix.Close(fd)
		return -1, ErrMaterial
	}
	return fd, nil
}

