response.text:
func (store MaterialStore) VerifyIdentityRekeyResponseKey(ctx context.Context, verified VerifiedIdentityRekey, inputs TrustInputs, wire []byte, now time.Time) error {
	dir, _, err := store.identityRekeyResponseKey(ctx, verified, inputs, wire, now)
	if err == nil {
		unix.Close(dir)
	}
	return err
}

func responseKeyPublic(wire []byte) (string, error) {
	key, err := base64.StdEncoding.Strict().DecodeString(strings.TrimSpace(string(wire)))
	if err != nil || len(key) != ed25519.PrivateKeySize {
		clear(key)
		return "", ErrMaterial
	}
	defer clear(key)
	derived := ed25519.NewKeyFromSeed(key[:ed25519.SeedSize])
	defer clear(derived)
	if !bytes.Equal(key, derived) {
		return "", ErrMaterial
	}
	return base64.StdEncoding.EncodeToString(key[ed25519.SeedSize:]), nil
}

func (store MaterialStore) identityRekeyResponseKey(ctx context.Context, verified VerifiedIdentityRekey, inputs TrustInputs, wire []byte, now time.Time) (int, bootstrap.SecretReference, error) {
	if os.Geteuid() != 0 || os.Getegid() != 0 {
		return -1, bootstrap.SecretReference{}, ErrMaterial
	}
	if err := ctx.Err(); err != nil {
		return -1, bootstrap.SecretReference{}, err
	}
	current, err := verified.VerifyCurrent(inputs, now)
	if err != nil {
		return -1, bootstrap.SecretReference{}, err
	}
	accepted := current.Accepted()
	name := accepted.Slot + "-response.key"
	ref, found := materialReferences(accepted, nil)[name]
	public, keyErr := responseKeyPublic(wire)
	if !found || keyErr != nil || public != current.journal.HostObservation.ResponseKey ||
		len(wire) == 0 || int64(len(wire)) > ref.MaxBytes || digest(wire) != ref.SHA256 {
		return -1, bootstrap.SecretReference{}, ErrMaterial
	}
	dir, err := openMaterialDirectory(store.installedDirectory, store.serviceUID, store.serviceGID, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return -1, bootstrap.SecretReference{}, err
	}
	if !memoryFilesystem(dir) {
		unix.Close(dir)
		return -1, bootstrap.SecretReference{}, ErrMaterial
	}
	old, err := readUnpinned(dir, name, store.serviceUID, store.serviceGID, bootstrap.MaxSecretBytes)
	defer clear(old)
	if err == nil && !bytes.Equal(old, wire) {
		previous, keyErr := responseKeyPublic(old)
		if keyErr != nil || previous != current.journal.HostObservation.PreviousResponseKey {
			err = ErrMaterial
		}
	}
	if err != nil {
		unix.Close(dir)
		return -1, bootstrap.SecretReference{}, err
	}
	return dir, ref, nil
}

// InstallIdentityRekeyResponseKey publishes only the exact root-authorized
// replacement. The caller holds the layout lock and rechecks stopped state
// before each effect; retries also accept the already installed exact key.
func (store MaterialStore) InstallIdentityRekeyResponseKey(ctx context.Context, verified VerifiedIdentityRekey, inputs TrustInputs, wire []byte, beforeEffect func(context.Context) error, now time.Time) error {
	if beforeEffect == nil {
		return ErrMaterial
	}
	dir, ref, err := store.identityRekeyResponseKey(ctx, verified, inputs, wire, now)
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	staging, err := openMaterialDirectory(store.stagingDirectory, 0, 0, 0o700, store.allowUnsafeAncestors)
	if err != nil {
		return err
	}
	defer unix.Close(staging)
	var nonce [16]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return err
	}
	child := ".identity-response-" + hex.EncodeToString(nonce[:])
	if err := beforeEffect(ctx); err != nil {
		return err
	}
	if err := unix.Mkdirat(staging, child, 0o700); err != nil {
		return err
	}
	defer unix.Unlinkat(staging, child, unix.AT_REMOVEDIR)
	stage, err := unix.Openat(staging, child, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if err != nil {
		return err
	}
	defer unix.Close(stage)
	defer unix.Unlinkat(stage, ref.TargetFile, 0)
	if err := store.writeStaged(stage, ref.TargetFile, wire); err != nil {
		return err
	}
	checked, _, err := store.identityRekeyResponseKey(ctx, verified, inputs, wire, time.Now().Round(0).UTC())
	if err != nil {
		return err
	}
	defer unix.Close(checked)
	if err := beforeEffect(ctx); err != nil {
		return err
	}
	if err := unix.Renameat(stage, ref.TargetFile, checked, ref.TargetFile); err != nil {
		return err
	}
	if err := unix.Fsync(checked); err != nil {
		return err
	}
	installed, err := readMaterial(checked, ref.TargetFile, store.serviceUID, store.serviceGID, ref.SHA256, ref.MaxBytes)
	clear(installed)
	return errors.Join(err, unix.Fsync(stage))
}

successor.text:
func (store MarkerStore) prepareIdentityRekeySuccessor(ctx context.Context, proposal IdentityRekeyJournal, js jetstream.JetStream, now time.Time, baked bakedStore) error {
	if uint32(os.Geteuid()) != store.ownerUID || store.ownerUID == 0 && os.Getegid() != 0 {
		return ErrIdentityRekeyJournal
	}
	verified, _, err := verifyIdentityRekeyInstall(store, baked, proposal, now, false)
	if err != nil {
		return err
	}
	if existing, err := store.readIdentityRekeyJournal(); err == nil {
		wire, err := encodeIdentityRekeyJournal(existing)
		if err != nil {
			return err
		}
		if bytes.Equal(wire, verified.Wire()) {
			return ctx.Err()
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	accepted, err := store.ReadIdentity()
	if err != nil {
		// The first cutover's opaque predecessor is not a successor acceptance.
		if existing, readErr := store.readIdentityRekeyJournal(); errors.Is(readErr, os.ErrNotExist) {
			return nil
		} else if readErr == nil && bytes.Equal(existing.AcceptedWire, proposal.AcceptedWire) {
			return nil
		}
		return err
	}
	if accepted.Origin != identityrekey.AcceptanceOriginRekey {
		return nil
	}
	wire, err := EncodeAcceptedIdentity(accepted)
	if err != nil || digest(wire) != proposal.PreviousAcceptanceSHA256 {
		return errors.Join(ErrAcceptancePredecessor, err)
	}
	target, err := DecodeAcceptedIdentity(proposal.AcceptedWire)
	if err != nil || target.OperationID == accepted.OperationID {
		return errors.Join(ErrIdentityRekeyJournal, err)
	}
	inputs, err := baked.loadTrustInputs(accepted)
	if err != nil {
		return err
	}
	if err := store.verifyIdentityRekeyCompletion(ctx, accepted, inputs, js); err != nil {
		return err
	}
	retained, err := store.verifiedIdentityRekey(accepted, inputs)
	if err != nil {
		return err
	}
	dir, err := store.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	actual, err := store.readIdentityBytes(dir, markerName)
	if err != nil || !bytes.Equal(actual, wire) {
		return errors.Join(ErrAcceptancePredecessor, err)
	}
	existing, err := store.readIdentityRekeyJournal()
	if errors.Is(err, os.ErrNotExist) {
		return nil // Exact archived acceptance was independently verified above.
	}
	if err != nil {
		return err
	}
	existingWire, err := encodeIdentityRekeyJournal(existing)
	if err != nil || !bytes.Equal(existingWire, retained.Wire()) {
		return ErrIdentityRekeyJournal
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if _, _, err := verifyIdentityRekeyInstall(store, baked, proposal, time.Now().Round(0).UTC(), false); err != nil {
		return err
	}
	if err := unix.Renameat2(dir, identityRekeyJournalName, dir, identityRekeyAcceptedJournalName(wire), unix.RENAME_NOREPLACE); err != nil {
		return err
	}
	return unix.Fsync(dir)
}

completion.text:
func (store MarkerStore) verifyIdentityRekeyCompletion(ctx context.Context, accepted AcceptedIdentity, inputs TrustInputs, js jetstream.JetStream) error {
	wire, err := EncodeAcceptedIdentity(accepted)
	if err != nil {
		return err
	}
	actual, err := store.ReadIdentity()
	if err != nil {
		return err
	}
	fresh, err := EncodeAcceptedIdentity(actual)
	if err != nil || !bytes.Equal(wire, fresh) {
		return ErrIdentityRekeyLocalPending
	}
	verified, err := store.verifiedIdentityRekey(actual, inputs)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	envelope, err := verified.ResetEnvelope()
	if err != nil {
		return err
	}
	sequence, err := authority.IdentityResetCompletion(ctx, js, envelope, verified.AcceptedRoots(), verified.ResetTarget(), actual.AcceptedAt)
	if err != nil {
		return err
	}
	if sequence == 0 {
		return ErrIdentityRekeyPending
	}
	// A network wait cannot turn an obsolete local acceptance into readiness.
	_, err = store.verifiedIdentityRekey(actual, inputs)
	return err
}

