func (store bakedStore) loadAcceptedHostLaunchMaterial(accepted AcceptedIdentity, markers MarkerStore) (LaunchMaterial, error) {
	wires, err := store.loadAcceptedLaunchFiles(accepted, markers, acceptedLaunchNames[:2])
	if err != nil {
		return LaunchMaterial{}, err
	}
	if err := validateHostLaunchInputs(wires[HostEnrollmentFilename], wires[OperatorSSHKeyFilename], accepted.Cell, accepted.Environment); err != nil {
		return LaunchMaterial{}, err
	}
	return LaunchMaterial{HostEnrollment: wires[HostEnrollmentFilename], OperatorSSHKey: wires[OperatorSSHKeyFilename]}, nil
}

// LoadAcceptedManagedImageMaterial checks installed pins; the launcher must
// independently verify CURRENT release qualification against its configured image.
func LoadAcceptedManagedImageMaterial(accepted AcceptedIdentity) (receipt, delegation []byte, err error) {
	store := bakedStore{directory: BakedDirectory, chainFile: RootChainFile}
	return store.loadAcceptedManagedImageMaterial(accepted, NewMarkerStore())
}

func (store bakedStore) loadAcceptedManagedImageMaterial(accepted AcceptedIdentity, markers MarkerStore) ([]byte, []byte, error) {
	wires, err := store.loadAcceptedLaunchFiles(accepted, markers, acceptedLaunchNames[2:])
	if err != nil {
		return nil, nil, err
	}
	return wires[ManagedHostImageReceiptFilename], wires[ManagedHostImageDelegationFilename], nil
}

func (store bakedStore) loadAcceptedLaunchFiles(accepted AcceptedIdentity, markers MarkerStore, names []string) (map[string][]byte, error) {
	if err := accepted.Validate(); err != nil {
		return nil, err
	}
	installed, err := markers.ReadIdentity()
	if err != nil {
		return nil, err
	}
	want, err := EncodeAcceptedIdentity(accepted)
	if err != nil {
		return nil, err
	}
	actual, err := EncodeAcceptedIdentity(installed)
	if err != nil || !bytes.Equal(want, actual) {
		return nil, ErrLaunchMaterial
	}
	inputs, err := store.loadTrustInputs(accepted)
	if err != nil {
		return nil, err
	}
	if _, err := markers.verifiedIdentityRekey(accepted, inputs); err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, err
	}
	wires, err := store.readLaunchFiles(names)
	if err != nil {
		return nil, err
	}
	for name, wire := range wires {
		if digest(wire) != accepted.LaunchMaterialSHA256[name] {
			return nil, fmt.Errorf("%w: accepted launch input %s differs", ErrLaunchMaterial, name)
		}
	}
	if err := (Gate{Markers: markers, trustStore: &store}).checkAcceptedUnchanged(accepted); err != nil {
		return nil, err
	}
	return wires, nil
}

func (store bakedStore) readLaunchFiles(names []string) (map[string][]byte, error) {
	dir, err := store.openDirectory(store.directory)
	if err != nil {
		return nil, err
	}
	defer unix.Close(dir)
	wires := make(map[string][]byte, len(names))
	for _, name := range names {
		maximum := int64(trust.MaxEnvelopeBytes)
		switch name {
		case HostEnrollmentFilename:
			maximum = hostenroll.MaxPublicBundleBytes
		case OperatorSSHKeyFilename:
			maximum = maxOperatorSSHKey
		case ManagedHostImageReceiptFilename, ManagedHostImageDelegationFilename:
		default:
			return nil, ErrLaunchMaterial
		}
		wire, err := store.readFile(dir, name, maximum)
		if err != nil {
			return nil, fmt.Errorf("read root-owned public launch input %s: %w", name, err)
		}
		wires[name] = wire
	}
	return wires, nil
}

func validateHostLaunchInputs(enrollment, ssh []byte, cell, environment string) error {
	bundle, err := hostenroll.ParsePublicBundle(enrollment)
	if err != nil {
		return err
	}
	if err := bundle.MatchesImageLayout(); err != nil {
		return err
	}
	if bundle.Cell != strings.ToLower(cell) || bundle.Region != cell || bundle.Environment != environment {
		return ErrLaunchMaterial
	}
	return validateOperatorSSHKey(ssh)
}

baked_files.text:
func (store bakedStore) loadRoots() (trust.Keyring, error) {
	rootsDir, err := store.openDirectory(filepath.Join(store.directory, "trust-roots"))
	if err != nil {
		return nil, fmt.Errorf("open baked trust roots: %w", err)
	}
	file := os.NewFile(uintptr(rootsDir), "trust-roots")
	defer file.Close()
	names, err := file.Readdirnames(-1)
	if err != nil {
		return nil, fmt.Errorf("read baked root entries: %w", err)
	}
	if len(names) == 0 || len(names) > MaxRootFiles {
		return nil, ErrBakedInputs
	}
	sort.Strings(names)
	keys := make([]ed25519.PublicKey, 0, len(names))
	total := 0
	for _, name := range names {
		if !rootFilenameRE.MatchString(name) || name == "000.pem" {
			return nil, ErrBakedInputs
		}
		wire, err := store.readFile(rootsDir, name, MaxRootBytes)
		if err != nil {
			return nil, fmt.Errorf("read baked root %s: %w", name, err)
		}
		total += len(wire)
		if total > MaxRootsTotal {
			return nil, ErrBakedInputs
		}
		block, rest := pem.Decode(wire)
		if block == nil || block.Type != "PUBLIC KEY" || len(block.Headers) != 0 || len(bytes.TrimSpace(rest)) != 0 {
			return nil, ErrBakedInputs
		}
		publicKey, err := x509.ParsePKIXPublicKey(block.Bytes)
		key, ok := publicKey.(ed25519.PublicKey)
		if err != nil || !ok || len(key) != ed25519.PublicKeySize {
			return nil, ErrBakedInputs
		}
		keys = append(keys, key)
	}
	roots, err := trust.ParseKeyring(keys...)
	if err != nil {
		return nil, fmt.Errorf("assemble unambiguous root key IDs: %w", err)
	}
	return roots, nil
}

func (store bakedStore) openDirectory(path string) (int, error) {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return -1, ErrBakedInputs
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	for _, component := range strings.Split(strings.TrimPrefix(path, "/"), "/") {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrBakedInputs
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			!store.allowUnsafeAncestors && (stat.Uid != 0 || stat.Gid != 0 || stat.Mode&0o777 != 0o755) {
			unix.Close(fd)
			return -1, ErrBakedInputs
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil ||
		stat.Uid != store.ownerUID || stat.Gid != store.ownerGID || stat.Mode&0o777 != 0o755 {
		unix.Close(fd)
		return -1, ErrBakedInputs
	}
	return fd, nil
}

func (store bakedStore) readFile(dir int, name string, maximum int64) ([]byte, error) {
	if strings.Contains(name, "/") || name == "" || maximum <= 0 {
		return nil, ErrBakedInputs
	}
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || stat.Gid != store.ownerGID ||
		stat.Mode&0o7777 != 0o444 || stat.Nlink != 1 || stat.Size <= 0 || stat.Size > maximum {
		return nil, ErrBakedInputs
	}
	wire, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || len(wire) == 0 || int64(len(wire)) > maximum {
		return nil, ErrBakedInputs
	}
	return wire, nil
}

authority_reset.text:
func ResetIdentityLease(ctx context.Context, js jetstream.JetStream, envelope trust.Envelope,
	roots trust.Keyring, target IdentityResetTarget, now time.Time,
) (uint64, error) {
	reset, err := VerifyIdentityReset(envelope, roots, target, now)
	if err != nil {
		return 0, err
	}
	if js == nil {
		return 0, errors.New("identity reset requires JetStream")
	}
	bounded, cancel := context.WithTimeout(ctx, authorityAPITimeout)
	defer cancel()
	stream, err := js.Stream(bounded, ControlStreamName)
	if err != nil {
		return 0, fmt.Errorf("open existing identity reset stream: %w", err)
	}
	info, err := stream.Info(bounded)
	if err != nil {
		return 0, err
	}
	if err := verifyControlStreamConfig(info.Config, target.Replicas); err != nil {
		return 0, err
	}
	subject := fmt.Sprintf("%s.%s.lease", controlSubjectRoot, reset.Scope)
	barrier, err := identityResetLease(reset, resetDigest(envelope.Payload))
	if err != nil {
		return 0, err
	}
	previous, err := stream.GetLastMsgForSubject(bounded, subject)
	if err != nil {
		return 0, err
	}
	if bytes.Equal(previous.Data, barrier) {
		if previous.Sequence != reset.LastSequence+1 {
			return 0, ErrConflict
		}
		if _, err := verifyCommittedIdentityReset(ctx, js, envelope, roots, target); err != nil {
			return 0, err
		}
		return previous.Sequence, nil
	}
	if info.State.LastSeq != reset.LastSequence || previous.Sequence != reset.PreviousSequence ||
		resetDigest(previous.Data) != reset.PreviousSHA256 {
		return 0, ErrConflict
	}
	if err := verifyIdentityResetGlobalPredecessor(bounded, stream, reset); err != nil {
		return 0, err
	}
	if err := verifyIdentityResetHostInventory(ctx, js, reset, target.Replicas); err != nil {
		return 0, err
	}
	if reset.GlobalLease != nil {
		return publishIdentityResetBatch(ctx, js, stream, reset, envelope, roots, target)
	}
	ack, publishErr := js.PublishMsg(bounded, controlMessage(subject, "lease", reset.OperationID, barrier),
		jetstream.WithExpectLastSequence(reset.LastSequence),
		jetstream.WithExpectLastSequenceForSubject(reset.PreviousSequence, subject))
	if isSequenceConflict(publishErr) {
		return 0, ErrConflict
	}
	// A lost publish reply is resolved only by leader-backed exact readback.
	probe, probeCancel := context.WithTimeout(context.WithoutCancel(ctx), authorityAPITimeout)
	defer probeCancel()
	readInfo, readErr := stream.Info(probe)
	if readErr == nil {
		readErr = verifyControlStreamConfig(readInfo.Config, target.Replicas)
	}
	if readErr != nil {
		return 0, fmt.Errorf("%w: identity reset policy readback: %w", ErrOutcomeUnknown, errors.Join(publishErr, readErr))
	}
	stored, readErr := stream.GetLastMsgForSubject(probe, subject)
	if readErr != nil {
		return 0, fmt.Errorf("%w: identity reset confirmation: %w", ErrOutcomeUnknown, errors.Join(publishErr, readErr))
	}
	if !bytes.Equal(stored.Data, barrier) || publishErr == nil && (ack == nil || stored.Sequence != ack.Sequence) {
		if publishErr != nil && stored.Sequence == reset.PreviousSequence {
			return 0, fmt.Errorf("identity reset publish: %w", publishErr)
		}
		return 0, ErrConflict
	}
	if _, err := verifyCommittedIdentityReset(probe, js, envelope, roots, target); err != nil {
		return 0, fmt.Errorf("%w: committed reset needs current-root recovery authorization: %w", ErrOutcomeUnknown, err)
	}
	return stored.Sequence, nil
}

authority_replace.text:
func ReplaceIdentityRecords(ctx context.Context, js jetstream.JetStream, envelope trust.Envelope, roots trust.Keyring,
	target IdentityResetTarget, values [][]byte, _ time.Time,
) ([]uint64, error) {
	reset, err := verifyCommittedIdentityReset(ctx, js, envelope, roots, target)
	if err != nil {
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			err = errors.Join(ErrFenced, err)
		}
		return nil, err
	}
	if js == nil || js.Conn() == nil || len(values) != len(reset.Records) {
		return nil, errors.New("identity replacement requires JetStream and every pinned value")
	}
	values = slices.Clone(values)
	for index, record := range reset.Records {
		values[index] = bytes.Clone(values[index])
		if err := validateIdentityRecordValue(reset, record, values[index]); err != nil {
			return nil, err
		}
	}
	if err := holdIdentityResetGlobalLease(ctx, js, reset, resetDigest(envelope.Payload), target.Replicas); err != nil {
		return nil, err
	}
	reader, err := identityRecordReader(js)
	if err != nil {
		return nil, err
	}
	pinID := resetDigest(envelope.Payload)
	revisions := make([]uint64, len(reset.Records))
	for index, record := range reset.Records {
		get := heldIdentityRecordReader(js, reader, reset, record, pinID, target.Replicas)
		previous, err := get(ctx)
		revision := uint64(0)
		if errors.Is(err, nats.ErrMsgNotFound) && record.PreviousRevision == 0 {
			// Even an explicitly absent delete must commit its own positive tombstone.
		} else if err != nil {
			return nil, err
		} else if identityRecordComplete(record, previous, pinID) {
			revisions[index] = previous.Sequence
			continue
		} else if record.Action == IdentityResetReplaceKV && identityRecordPurge(record, previous, pinID) {
			revision = previous.Sequence
		} else if identityRecordPredecessor(record, previous) {
			revision = previous.Sequence
		} else {
			return nil, fmt.Errorf("%w: identity predecessor %s/%s changed", ErrConflict, record.Bucket, record.Key)
		}
		if record.Action != IdentityResetAppendHostHead && (record.Action == IdentityResetDeleteKV || revision == record.PreviousRevision && revision != 0) {
			purge := nats.NewMsg(identityRecordSubject(record))
			purge.Header.Set("KV-Operation", "PURGE")
			purge.Header.Set(nats.MsgRollup, nats.MsgRollupSubject)
			purge.Header.Set(rekeyPinsHeader, pinID)
			purge.Header.Set(nats.MsgIdHdr, reset.OperationID+":"+record.Bucket+":"+record.Key+":purge")
			if revision, err = publishHeldIdentityRecord(ctx, js, reset, record, pinID, target.Replicas, purge, revision, get); err != nil {
				return nil, err
			}
		}
		if record.Action == IdentityResetDeleteKV {
			revisions[index] = revision
			continue
		}
		create := nats.NewMsg(identityRecordSubject(record))
		create.Data = values[index]
		create.Header.Set(rekeyPinsHeader, pinID)
		create.Header.Set(nats.MsgIdHdr, reset.OperationID+":"+record.Bucket+":"+record.Key+":create")
		if record.Action == IdentityResetAppendHostHead {
			head, _ := decodeControlRecord(create.Data) // Every value was validated before effects.
			create.Header.Set("TerraScale-Control-Kind", string(head.Kind))
			create.Header.Set("TerraScale-Operation-ID", head.OperationID)
		}
		if revisions[index], err = publishHeldIdentityRecord(ctx, js, reset, record, pinID, target.Replicas, create, revision, get); err != nil {
			return nil, err
		}
	}
	if err := verifyResetBarrier(ctx, js, reset, pinID, target.Replicas); err != nil {
		return nil, err
	}
	return revisions, nil
}

authority_complete.text:
func CompleteIdentityReset(ctx context.Context, js jetstream.JetStream, envelope trust.Envelope, roots trust.Keyring,
	target IdentityResetTarget, _ time.Time,
) (uint64, error) {
	reset, err := verifyCommittedIdentityReset(ctx, js, envelope, roots, target)
	if err != nil {
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			err = errors.Join(ErrFenced, err)
		}
		return 0, err
	}
	if js == nil || js.Conn() == nil {
		return 0, errors.New("identity reset completion requires JetStream")
	}
	pinID := resetDigest(envelope.Payload)
	if sequence, err := identityResetCompletion(ctx, js, reset, pinID, target.Replicas); err != nil || sequence != 0 {
		return sequence, err
	}
	if err := verifyResetBarrier(ctx, js, reset, pinID, target.Replicas); err != nil {
		return 0, err
	}
	reader, err := identityRecordReader(js)
	if err != nil {
		return 0, err
	}
	// Capture the log floor before checking host heads so completion CAS also
	// fences changes between those checks and the release.
	snapshotCtx, snapshotCancel := context.WithTimeout(ctx, authorityAPITimeout)
	stream, err := js.Stream(snapshotCtx, ControlStreamName)
	if err != nil {
		snapshotCancel()
		return 0, err
	}
	info, err := stream.Info(snapshotCtx)
	snapshotCancel()
	if err != nil {
		return 0, err
	}
	if err := verifyControlStreamConfig(info.Config, target.Replicas); err != nil {
		return 0, err
	}
	if err := verifyIdentityResetHostInventory(ctx, js, reset, target.Replicas); err != nil {
		return 0, err
	}
	for _, record := range reset.Records {
		msg, err := heldIdentityRecordReader(js, reader, reset, record, pinID, target.Replicas)(ctx)
		if err != nil {
			return 0, err
		}
		if !identityRecordComplete(record, msg, pinID) {
			return 0, fmt.Errorf("%w: identity replacement %s/%s is incomplete", ErrConflict, record.Bucket, record.Key)
		}
		if record.Action == IdentityResetAppendHostHead {
			if err := validateIdentityRecordValue(reset, record, msg.Data); err != nil {
				return 0, err
			}
		}
	}

	bounded, cancel := context.WithTimeout(ctx, authorityAPITimeout)
	defer cancel()
	subject := fmt.Sprintf("%s.%s.lease", controlSubjectRoot, reset.Scope)
	previous, err := stream.GetLastMsgForSubject(bounded, subject)
	if err != nil {
		return 0, err
	}
	if err := verifyResetBarrier(bounded, js, reset, pinID, target.Replicas); err != nil {
		return 0, err
	}
	if reset.GlobalLease != nil {
		return completeIdentityResetBatch(ctx, js, stream, reset, pinID, info.State.LastSeq, target.Replicas)
	}
	complete, err := identityResetLease(reset, "")
	if err != nil {
		return 0, err
	}
	ack, publishErr := js.PublishMsg(bounded, controlMessage(subject, "lease", reset.OperationID+":complete", complete),
		jetstream.WithExpectLastSequence(info.State.LastSeq),
		jetstream.WithExpectLastSequenceForSubject(previous.Sequence, subject))
	probe, probeCancel := context.WithTimeout(context.WithoutCancel(ctx), authorityAPITimeout)
	defer probeCancel()
	// Immutable log readback still confirms completion if a controller acquired
	// normal authority before the publish reply arrived.
	stored, readErr := stream.GetMsg(probe, info.State.LastSeq+1)
	if readErr == nil && stored.Subject == subject && bytes.Equal(stored.Data, complete) &&
		(publishErr != nil || ack != nil && stored.Sequence == ack.Sequence) {
		return stored.Sequence, nil
	}
	if isSequenceConflict(publishErr) {
		return 0, ErrConflict
	}
	if readErr == nil {
		readErr = ErrConflict
	}
	return 0, fmt.Errorf("%w: identity reset completion: %w", ErrOutcomeUnknown, errors.Join(publishErr, readErr))
}

authority_completion.text:
func IdentityResetCompletion(ctx context.Context, js jetstream.JetStream, envelope trust.Envelope, roots trust.Keyring,
	target IdentityResetTarget, now time.Time,
) (uint64, error) {
	reset, err := VerifyIdentityReset(envelope, roots, target, now)
	if err != nil {
		return 0, err
	}
	if js == nil {
		return 0, errors.New("identity reset outcome requires JetStream")
	}
	committed, err := IdentityResetCommitted(ctx, js, envelope, roots, target)
	if err != nil || !committed {
		return 0, err
	}
	return identityResetCompletion(ctx, js, reset, resetDigest(envelope.Payload), target.Replicas)
}

func identityResetCompletion(ctx context.Context, js jetstream.JetStream, reset IdentityReset, pinID string, replicas int) (uint64, error) {
	bounded, cancel := context.WithTimeout(ctx, authorityAPITimeout)
	defer cancel()
	stream, err := js.Stream(bounded, ControlStreamName)
	if err != nil {
		return 0, err
	}
	info, err := stream.Info(bounded)
	if err != nil {
		return 0, err
	}
	if err := verifyControlStreamConfig(info.Config, replicas); err != nil {
		return 0, err
	}
	barrier, err := stream.GetMsg(bounded, reset.LastSequence+1)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return 0, nil
	}
	if err != nil {
		return 0, err
	}
	subject := fmt.Sprintf("%s.%s.lease", controlSubjectRoot, reset.Scope)
	wantBarrier, err := identityResetLease(reset, pinID)
	if err != nil {
		return 0, err
	}
	if barrier.Subject != subject || !bytes.Equal(barrier.Data, wantBarrier) {
		return 0, ErrConflict
	}
	// No ordinary lease can follow the hold until completion; other scopes
	// may append between these two records without changing this outcome.
	completed, err := stream.GetMsg(bounded, barrier.Sequence+1, jetstream.WithGetMsgSubject(subject))
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return 0, nil
	}
	if err != nil {
		return 0, err
	}
	wantCompleted, err := identityResetLease(reset, "")
	if err != nil {
		return 0, err
	}
	if completed.Subject != subject || !bytes.Equal(completed.Data, wantCompleted) {
		return 0, ErrConflict
	}
	if reset.GlobalLease != nil {
		_, globalComplete, err := globalResetOutcome(bounded, stream, reset, pinID)
		if err != nil || globalComplete == 0 {
			return 0, errors.Join(ErrConflict, err)
		}
	}
	return completed.Sequence, nil
}

func checkIdentityBucket(ctx context.Context, js jetstream.JetStream, bucket string, replicas int) error {
	bounded, cancel := context.WithTimeout(ctx, authorityAPITimeout)
	defer cancel()
	stream, err := js.Stream(bounded, "KV_"+bucket)
	if err != nil {
		return err
	}
	info, err := stream.Info(bounded)
	if err != nil {
		return err
	}
	if info.Config.Replicas != replicas || info.Config.Storage != jetstream.FileStorage ||
		!info.Config.AllowRollup || info.Config.MaxAge != 0 || info.Config.Retention != jetstream.LimitsPolicy ||
		(info.Config.MaxMsgs > 0 || info.Config.MaxBytes > 0) && info.Config.Discard != jetstream.DiscardNew ||
		len(info.Config.Subjects) != 1 || info.Config.Subjects[0] != "$KV."+bucket+".>" ||
		info.Config.Mirror != nil || len(info.Config.Sources) != 0 || info.Config.SubjectTransform != nil || info.Config.RePublish != nil ||
		info.Config.Sealed || info.Config.NoAck || info.Config.AllowMsgTTL || info.Config.SubjectDeleteMarkerTTL != 0 {
		return errors.New("identity replacement bucket must preserve the durable replica quorum and permit exact-key purges")
	}
	return nil
}

func identityRecordReader(js jetstream.JetStream) (nats.JetStreamContext, error) {
	options := js.Options()
	var readOptions []nats.JSOpt
	if options.Domain != "" {
		readOptions = append(readOptions, nats.Domain(options.Domain))
	} else if options.APIPrefix != "" {
		readOptions = append(readOptions, nats.APIPrefix(options.APIPrefix))
	}
	return js.Conn().JetStream(readOptions...)
}

durable_write.text:
func writeSynced(path string, data []byte) error {
	file, err := os.CreateTemp(filepath.Dir(path), ".generation-config-")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	if err := file.Chmod(0o644); err != nil {
		return err
	}
	if _, err := file.Write(data); err != nil {
		return err
	}
	if err := file.Sync(); err != nil {
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Rename(file.Name(), path); err != nil {
		return err
	}
	return syncDirectory(filepath.Dir(path))
}

func syncDirectory(path string) error {
	dir, err := os.Open(path)
	if err != nil {
		return err
	}
	defer dir.Close()
	return dir.Sync()
}
